/** 修改当前用户资料：PATCH /api/auth/profile {name?, bio?, defaultModel?, avatar?} */
function handleProfile(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  readBody(req).then(async body => {
    const user = auth.user;
    if (body.name !== undefined) {
      const name = String(body.name || '').trim();
      if (name.length > 24) throw requestError(400, '昵称不能超过 24 个字符');
      user.name = name || String(user.email || '').split('@')[0].slice(0, 24);
    }
    if (Object.prototype.hasOwnProperty.call(body, 'avatar')) user.avatar = normalizeAvatar(body.avatar, '');
    if (body.bio !== undefined) {
      const bio = String(body.bio || '').trim();
      if (bio.length > 500) throw requestError(400, '个人简介不能超过 500 个字符');
      user.bio = bio;
    }
    if (body.defaultModel !== undefined) {
      const requestedModel = String(body.defaultModel || '').trim();
      if (requestedModel && !findPlatformModel(requestedModel)) throw requestError(400, '默认模型不存在或未配置');
      user.defaultModel = canChooseModel(user) ? (requestedModel || currentDefaultModel()) : currentDefaultModel();
    }
    if (POSTGRES_MODE) {
      const row = await postgresRepository.runtimeUpdateAccountProfile({
        actorUserId: auth.user.userId,
        userId: auth.user.userId,
        name: user.name,
        avatar: user.avatar,
        bio: user.bio,
        defaultModel: user.defaultModel
      });
      const saved = cachePostgresRuntimeUser(postgresRuntimeUserFromRow(row));
      if (saved && saved !== user) Object.assign(user, saved);
    } else {
      saveUser(user);
    }
    json(res, 200, { ok: true, user: publicUser(user) });
  }).catch(e => respondError(res, e));
}

/** GET /api/usage?limit=20 - current user's exact provider usage ledger */
function handleUsage(req, res) {
  const a = getAuthUser(req);
  if (!a) return json(res, 401, { error: '未登录' });
  let limit = 20;
  try {
    const value = Number(new URL(req.url, 'http://localhost').searchParams.get('limit'));
    if (Number.isFinite(value)) limit = Math.min(100, Math.max(1, Math.floor(value)));
  } catch (_) {}
  json(res, 200, { ok: true, usage: getUsageSummary(a.user.email, limit) });
}

/* ---------- 纠错库：摘要 / 扫描 / 回流 / 命中看板 ---------- */
let correctionHitsCache = null;
let correctionHitsDirty = false;
let correctionHitsTimer = null;

function loadCorrectionHits() {
  if (correctionHitsCache) return correctionHitsCache;
  try {
    const parsed = JSON.parse(fs.readFileSync(CORRECTION_HITS_FILE, 'utf8'));
    correctionHitsCache = parsed && typeof parsed === 'object' ? parsed : null;
  } catch (_) { correctionHitsCache = null; }
  if (!correctionHitsCache) correctionHitsCache = { schemaVersion: 'correction-hits-1', totalRequests: 0, passedRequests: 0, rules: {}, updatedAt: 0 };
  if (!correctionHitsCache.rules || typeof correctionHitsCache.rules !== 'object') correctionHitsCache.rules = {};
  return correctionHitsCache;
}

function flushCorrectionHits() {
  correctionHitsTimer = null;
  if (!correctionHitsDirty || !correctionHitsCache) return;
  correctionHitsDirty = false;
  try {
    fs.mkdirSync(CORRECTION_LIBRARY_DIR, { recursive: true });
    const tmp = CORRECTION_HITS_FILE + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(correctionHitsCache, null, 2), 'utf8');
    fs.renameSync(tmp, CORRECTION_HITS_FILE);
  } catch (error) {
    console.error('[correction] 命中统计保存失败：', error && error.message || error);
  }
}

function recordCorrectionHits(audit, meta = {}) {
  if (!audit || !audit.enabled) return;
  const hits = loadCorrectionHits();
  hits.totalRequests = (Number(hits.totalRequests) || 0) + 1;
  if (audit.status === 'passed') hits.passedRequests = (Number(hits.passedRequests) || 0) + 1;
  const seenInRequest = new Set();
  for (const finding of Array.isArray(audit.findings) ? audit.findings : []) {
    const id = String(finding && finding.ruleId || '').trim();
    if (!id) continue;
    const entry = hits.rules[id] || (hits.rules[id] = { label: finding.label || id, severity: finding.severity || '', hits: 0, requests: 0, editorOnlyHits: 0, lastText: '', lastAt: 0 });
    entry.label = finding.label || entry.label;
    entry.hits += 1;
    if (meta.editorOnly) entry.editorOnlyHits += 1;
    if (!seenInRequest.has(id)) { entry.requests += 1; seenInRequest.add(id); }
    entry.lastText = String(finding.text || '').slice(0, 60);
    entry.lastAt = Date.now();
  }
  hits.updatedAt = Date.now();
  correctionHitsDirty = true;
  if (!correctionHitsTimer) correctionHitsTimer = setTimeout(flushCorrectionHits, 2000);
}

function correctionLibrarySummary(library) {
  if (!library) return null;
  return {
    title: library.title,
    version: library.version,
    path: library.path,
    bytes: library.bytes,
    stats: library.stats,
    warnings: library.warnings,
    rules: library.rules.map(rule => ({ id: rule.id, category: rule.category, must: rule.must, badExample: rule.badExample })),
    blacklist: library.blacklist,
    scenes: correctionLibraryLib.SCENE_PROFILES.map(scene => ({ id: scene.id, label: scene.label, ruleIds: scene.ruleIds }))
  };
}

/** GET /api/correction-library：登录用户读取结构化摘要（不含作品案例明细以外的敏感信息）。 */
function handleCorrectionLibrarySummary(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  const library = getCorrectionLibrary();
  if (!library) return json(res, 503, { error: '纠错库不可用' });
  const summary = correctionLibrarySummary(library);
  const params = new URL(req.url, 'http://localhost').searchParams;
  if (params.get('cases') === '1') {
    summary.cases = library.cases.map(item => ({ id: item.id, chapter: item.chapter, type: item.type, before: item.before, after: item.after, principle: item.principle, source: item.source }));
  }
  json(res, 200, { ok: true, library: summary });
}

/** POST /api/correction-library/scan：对任意正文执行纠错库扫描，priorText 为同一作品前文（用于跨章重复）。 */
function handleCorrectionLibraryScan(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  readBody(req, CHAT_MAX_JSON_BODY_BYTES).then(body => {
    const input = body && typeof body === 'object' ? body : {};
    const text = String(input.text || '');
    if (!text.trim()) throw requestError(400, '正文为空');
    const audit = scanUniversalCorrectionRisks(text, {
      genre: String(input.genre || '').trim(),
      priorText: String(input.priorText || '').slice(0, CORRECTION_PRIOR_TEXT_MAX_CHARS),
      limit: Math.min(200, Math.max(1, Number(input.limit) || 120))
    });
    json(res, 200, { ok: true, audit });
  }).catch(error => respondError(res, error));
}

/** POST /api/correction-library/inbox：编辑器把用户手改回流到待合并队列。 */
function handleCorrectionLibraryInbox(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  readBody(req).then(body => {
    const input = body && typeof body === 'object' ? body : {};
    const entry = correctionLibraryLib.appendInbox(CORRECTION_INBOX_FILE, { ...input, user: auth.user.email, source: 'user' });
    const pending = correctionLibraryLib.readInbox(CORRECTION_INBOX_FILE).length;
    json(res, 200, { ok: true, entry, pending });
  }).catch(error => respondError(res, error));
}

/** GET /api/correction-library/inbox：获取待合并回流队列。 */
function handleCorrectionLibraryInboxList(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  const pending = correctionLibraryLib.readInbox(CORRECTION_INBOX_FILE);
  json(res, 200, { ok: true, pending, count: pending.length });
}

/** GET /api/correction-library/stats：获取纠错库全量统计。 */
function handleCorrectionLibraryStats(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  const library = getCorrectionLibrary();
  if (!library) return json(res, 503, { error: '纠错库不可用' });
  const hits = loadCorrectionHits();
  const pending = correctionLibraryLib.readInbox(CORRECTION_INBOX_FILE);
  const blacklistCount = (library.blacklist || []).reduce((acc, cat) => acc + (cat.phrases ? cat.phrases.length : 0), 0);
  json(res, 200, {
    ok: true,
    stats: {
      version: library.version,
      ruleCount: (library.rules || []).length,
      caseCount: (library.cases || []).length,
      userCaseCount: (library.cases || []).filter(c => c.source === 'user').length,
      blacklistCount,
      checkCount: (library.checks || []).length,
      inboxPending: pending.length,
      hits: {
        totalRequests: hits.totalRequests || 0,
        passedRequests: hits.passedRequests || 0,
        updatedAt: hits.updatedAt || 0
      }
    }
  });
}

/** POST /api/correction-library/merge：执行 inbox 回流合并进《纠错库.md》并重新编译。 */
function handleCorrectionLibraryMerge(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  const scriptPath = path.join(__dirname, 'scripts', 'build-correction-library.mjs');
  const { execFile } = require('node:child_process');
  execFile(process.execPath, [scriptPath, '--merge-inbox'], (error, stdout, stderr) => {
    if (error) {
      return json(res, 500, { ok: false, error: '合并失败: ' + (error.message || String(error)), stderr });
    }
    correctionLibraryLib.clearCorrectionLibraryCache();
    const updatedLibrary = getCorrectionLibrary();
    json(res, 200, {
      ok: true,
      message: '合并完成',
      stdout: stdout ? stdout.trim() : '',
      version: updatedLibrary ? updatedLibrary.version : '',
      inboxPending: correctionLibraryLib.readInbox(CORRECTION_INBOX_FILE).length
    });
  });
}

/** GET /api/admin/correction-library：后台命中看板 + 待合并回流条目。 */
function handleAdminCorrectionLibrary(req, res) {
  const auth = requireAdmin(req, res);
  if (!auth) return;
  const library = getCorrectionLibrary();
  const hits = loadCorrectionHits();
  const rules = Object.entries(hits.rules || {}).map(([id, entry]) => ({ id, ...entry })).sort((a, b) => b.hits - a.hits);
  json(res, 200, {
    ok: true,
    library: correctionLibrarySummary(library),
    hits: { totalRequests: hits.totalRequests || 0, passedRequests: hits.passedRequests || 0, updatedAt: hits.updatedAt || 0, rules },
    inbox: correctionLibraryLib.readInbox(CORRECTION_INBOX_FILE).slice(-200)
  });
}

/** 退出登录：POST /api/auth/logout 或 POST /api/admin/auth/logout */
function handleLogout(req, res, expectedScope = 'client') {
  const auth = req.headers['authorization'] || '';
  const token = auth.replace(/^Bearer\s+/i, '').trim();
  if (token && !getAuthUser(req, expectedScope)) return json(res, 401, { error: '登录态无效或用途不匹配' });
  if (token) {
    const tokenHash = hashSessionToken(token);
    markSessionRevoked(tokenHash);
    sessions.delete(tokenHash);
    if (POSTGRES_MODE && postgresRepository.enabled) {
      void postgresRepository.revokeAuthSession(tokenHash).catch(error => {
        console.error('[sessions] PostgreSQL 会话撤销失败：' + String(error && error.code || 'pg_unavailable'));
      });
    } else if (dbReady()) {
      db.prepare('UPDATE auth_sessions SET revoked_at = ? WHERE token_hash = ?').run(Date.now(), tokenHash);
    }
  }
  if (!POSTGRES_MODE) persistSessions();
  json(res, 200, { ok: true });
}

function handleLogoutAll(req, res) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '未登录' });
  const userId = String(auth.user.userId || projectScope.stableUserId(auth.user.email)).trim();
  const email = String(auth.user.email || '').trim().toLowerCase();
  let removed = 0;
  for (const [tokenHash, record] of sessions.entries()) {
    if (record && (String(record.userId || '') === userId || !record.userId && String(record.email || '').toLowerCase() === email)) {
      markSessionRevoked(tokenHash);
      sessions.delete(tokenHash);
      removed += 1;
    }
  }
  if (POSTGRES_MODE && postgresRepository.enabled) {
    void postgresRepository.revokeAuthSessions(userId).catch(error => {
      console.error('[sessions] PostgreSQL 全部会话撤销失败：' + String(error && error.code || 'pg_unavailable'));
    });
  } else if (dbReady()) {
    db.prepare(`UPDATE auth_sessions SET revoked_at = ?
      WHERE (user_id = ? OR (user_id = '' AND email = ?)) AND revoked_at IS NULL`).run(Date.now(), userId, email);
  }
  if (!POSTGRES_MODE) persistSessions();
  json(res, 200, { ok: true, removed });
}

function requireAdmin(req, res) {
  const auth = getAuthUser(req, 'admin');
  if (!auth) {
    json(res, 401, { error: '请先登录' });
    return null;
  }
  if (!requireSqliteForPublic(req, res)) return null;
  if (!isAdminUser(auth.user)) {
    json(res, 403, { error: '仅管理员可以访问管理后台' });
    return null;
  }
  return auth;
}

function adminUserView(user, usageOverride) {
  const role = normalizeUserRole(user);
  const usage = usageOverride || getUsageSummary(user.email, false);
  return {
    email: user.email,
    name: user.name || '',
    role,
    level: role,
    credits: role === 'admin' ? null : Math.round((Number(user.credits) || 0) * 100) / 100,
    unlimitedCredits: role === 'admin',
    costMultiplier: role === 'admin' ? 0 : (role === 'vip' ? 1 : 2),
    creditSpent: Math.round((Number(user.spent) || 0) * 100) / 100,
    tokenUsage: usage,
    createdAt: user.createdAt || null
  };
}

function normalizeSkillTargets(value) {
  const list = Array.isArray(value) ? value.map(v => String(v)) : [];
  if (!list.length || list.includes('all')) return ['all'];
  const out = [...new Set(list.filter(v => SKILL_TARGETS.has(v) && v !== 'all'))];
  return out.length ? out : ['all'];
}

function makeGlobalSkill(body, existing) {
  const name = String(body.name !== undefined ? body.name : (existing && existing.name) || '').trim().slice(0, 120);
  const description = String(body.description !== undefined ? body.description : (existing && existing.description) || '').trim().slice(0, 500);
  const instruction = String(body.instruction !== undefined ? body.instruction : (existing && existing.instruction) || '').trim().slice(0, 1000000);
  if (!name || !instruction) throw new Error('Skill 名称和指令不能为空');
  const runtimeFiles = normalizeSkillRuntimeFiles(body.runtimeFiles !== undefined ? body.runtimeFiles : (existing && existing.runtimeFiles), body.files !== undefined ? body.files : (existing && existing.files), { strict: true });
  const files = skillFileNames(runtimeFiles, body.files !== undefined ? body.files : (existing && existing.files));
  const fileManifest = Array.isArray(body.fileManifest) ? body.fileManifest : (existing && existing.fileManifest) || [];
  return decorateSkillPrompt({
    id: existing ? existing.id : 'global-' + Date.now().toString(36) + crypto.randomBytes(4).toString('hex'),
    name, description, instruction, files, runtimeFiles, fileManifest, complete: skillRuntimeFilesComplete(files, runtimeFiles, fileManifest),
    targets: normalizeSkillTargets(body.targets !== undefined ? body.targets : (existing && existing.targets)),
    enabled: body.enabled === undefined ? (existing ? existing.enabled !== false : true) : body.enabled !== false,
    global: true,
    createdAt: existing ? existing.createdAt : Date.now(),
    updatedAt: Date.now()
  });
}

function builtinSkillsForAdmin() {
  return loadBuiltinSkills().map(skill => ({ ...skill, editable: false, global: false, source: 'builtin' }));
}

function globalUsageSummary() {
  if (dbReady()) {
    const row = db.prepare(`SELECT COUNT(*) AS request_count,
      COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,
      COALESCE(SUM(completion_tokens), 0) AS completion_tokens,
      COALESCE(SUM(reasoning_tokens), 0) AS reasoning_tokens,
      COALESCE(SUM(cached_tokens), 0) AS cached_tokens,
      COALESCE(SUM(cache_write_tokens), 0) AS cache_write_tokens,
      COALESCE(SUM(total_tokens), 0) AS total_tokens,
      SUM(CASE WHEN total_tokens IS NOT NULL THEN 1 ELSE 0 END) AS precise_request_count,
      SUM(CASE WHEN total_tokens IS NULL THEN 1 ELSE 0 END) AS usage_unavailable_count,
      COALESCE(SUM(credit_cost), 0) AS credit_spent
      FROM token_usage`).get();
    const prompt = Number(row.prompt_tokens) || 0;
    return {
      totalTokens: Number(row.total_tokens) || 0,
      promptTokens: prompt,
      completionTokens: Number(row.completion_tokens) || 0,
      reasoningTokens: Number(row.reasoning_tokens) || 0,
      cachedTokens: Number(row.cached_tokens) || 0,
      cacheWriteTokens: Number(row.cache_write_tokens) || 0,
      requestCount: Number(row.request_count) || 0,
      preciseRequestCount: Number(row.precise_request_count) || 0,
      usageUnavailableCount: Number(row.usage_unavailable_count) || 0,
      cacheHitRate: prompt > 0 ? Math.round((Number(row.cached_tokens) || 0) / prompt * 10000) / 10000 : 0,
      creditSpent: Math.round((Number(row.credit_spent) || 0) * 100) / 100
    };
  }
  const rows = usageRowsFromJson();
  const summary = buildUsageSummary(rows);
  summary.creditSpent = Math.round(rows.reduce((n, row) => n + (Number(row.creditCost) || 0), 0) * 100) / 100;
  return summary;
}

function handleAdminOverview(req, res) {
  const auth = requireAdmin(req, res);
  if (!auth) return;
  if (!requireSqliteForPublic(req, res)) return;
  let page = 1, pageSize = 100, query = '', roleFilter = 'all';
  try {
    const params = new URL(req.url, 'http://localhost').searchParams;
    page = Math.max(1, Math.floor(Number(params.get('page')) || 1));
    pageSize = Math.min(200, Math.max(20, Math.floor(Number(params.get('pageSize')) || 100)));
    query = String(params.get('q') || '').trim().slice(0, 120);
    roleFilter = String(params.get('role') || 'all').trim().toLowerCase();
    if (!ACCOUNT_ROLES.has(roleFilter) && roleFilter !== 'all') roleFilter = 'all';
  } catch (_) {}
  const usageByUser = getUsageSummariesByUser();
  let users = [];
  let totalUsers = 0;
  const counts = { admin: 0, vip: 0, normal: 0 };
  if (dbReady()) {
    const rows = db.prepare('SELECT role, COUNT(*) AS n FROM accounts GROUP BY role').all();
    rows.forEach(row => { const key = ACCOUNT_ROLES.has(String(row.role)) ? String(row.role) : 'normal'; counts[key] += Number(row.n) || 0; });
    const where = [], args = [];
    if (roleFilter !== 'all') { where.push('role = ?'); args.push(roleFilter); }
    if (query) { where.push("(LOWER(email) LIKE ? ESCAPE '\\' OR LOWER(name) LIKE ? ESCAPE '\\')"); const like = '%' + query.toLowerCase().replace(/[\\%_]/g, '\\$&') + '%'; args.push(like, like); }
    const whereSql = where.length ? ' WHERE ' + where.join(' AND ') : '';
    totalUsers = Number(db.prepare('SELECT COUNT(*) AS n FROM accounts' + whereSql).get(...args).n) || 0;
    const rowsPage = db.prepare(`SELECT email, name, avatar, salt, pwd, role, level, plan, credits, spent, created_at AS createdAt
      FROM accounts${whereSql} ORDER BY created_at ASC LIMIT ? OFFSET ?`).all(...args, pageSize, (page - 1) * pageSize);
    users = rowsPage.map(user => adminUserView(userFromDbRow(user), usageByUser.get(user.email)));
  } else {
    const allUsers = loadUsers().filter(Boolean);
    allUsers.forEach(user => { const key = normalizeUserRole(user); counts[key] = (counts[key] || 0) + 1; });
    const filtered = allUsers.filter(user => {
      const matchesRole = roleFilter === 'all' || normalizeUserRole(user) === roleFilter;
      const value = String(user.email || '') + ' ' + String(user.name || '');
      return matchesRole && (!query || value.toLowerCase().includes(query.toLowerCase()));
    });
    totalUsers = filtered.length;
    users = filtered.slice((page - 1) * pageSize, page * pageSize).map(user => adminUserView(user, usageByUser.get(user.email)));
  }
  const usage = globalUsageSummary();
  const globals = loadGlobalSkills();
  json(res, 200, {
    ok: true,
    stats: {
      totalUsers: counts.admin + counts.vip + counts.normal,
      adminUsers: counts.admin,
      vipUsers: counts.vip,
      normalUsers: counts.normal,
      totalTokens: usage.totalTokens,
      requestCount: usage.requestCount,
      creditSpent: usage.creditSpent,
      cacheHitRate: usage.cacheHitRate
    },
    pagination: { page, pageSize, total: totalUsers, totalPages: Math.max(1, Math.ceil(totalUsers / pageSize)), query, role: roleFilter },
    usage,
    users,
    skills: { global: globals.length, enabled: globals.filter(s => s.enabled !== false).length, builtin: builtinSkillsForAdmin().length },
    audit: loadAdminAudit(8)
  });
}

function handleAdminUserPatch(req, res, email) {
  const auth = requireAdmin(req, res);
  if (!auth) return;
  let targetEmail;
  try { targetEmail = decodePathParam(email).trim().toLowerCase(); }
  catch (e) { return respondError(res, e); }
  const users = loadUsers();
  const user = users.find(u => String(u.email || '').toLowerCase() === targetEmail);
  if (!user) return json(res, 404, { error: '用户不存在' });
  readBody(req).then(async body => {
    const currentRole = normalizeUserRole(user);
    const nextRole = body.role === undefined ? currentRole : String(body.role).trim().toLowerCase();
    if (!ACCOUNT_ROLES.has(nextRole)) throw new Error('用户等级只能是 admin、vip 或 normal');
    if (isConfiguredAdminEmail(user.email) && nextRole !== 'admin') throw new Error('系统管理员邮箱不能降级');
    if (currentRole === 'admin' && nextRole !== 'admin') {
      const adminCount = users.filter(u => normalizeUserRole(u) === 'admin').length;
      if (adminCount <= 1) throw new Error('不能删除最后一个管理员');
    }
    if (body.name !== undefined) {
      const name = String(body.name).trim().slice(0, 24);
      if (!name) throw new Error('用户名称不能为空');
      user.name = name;
    }
    if (body.credits !== undefined) {
      const credits = Number(body.credits);
      if (!Number.isFinite(credits) || credits < 0 || credits > 1000000000000) throw new Error('积分必须是 0 到 1e12 之间的数字');
      user.credits = Math.round(credits * 100) / 100;
    } else if (currentRole === 'admin' && nextRole !== 'admin' && !Number.isFinite(Number(user.credits))) {
      user.credits = 500;
    }
    user.role = nextRole;
    user.level = nextRole;
    user.plan = nextRole;
    // Persist only the edited account so a concurrent AI settlement cannot
    // be overwritten by a stale full-user snapshot.
    if (POSTGRES_MODE) {
      const row = await postgresRepository.runtimeUpdateAccount({
        actorUserId: auth.user.userId,
        userId: user.userId,
        name: user.name,
        avatar: user.avatar,
        bio: user.bio,
        defaultModel: user.defaultModel,
        salt: user.salt,
        pwd: user.pwd,
        role: user.role,
        level: user.level,
        plan: user.plan,
        credits: user.credits,
        spent: user.spent,
        createdAtText: user.createdAt,
        preserveFinancials: body.credits === undefined
      });
      const saved = cachePostgresRuntimeUser(postgresRuntimeUserFromRow(row));
      if (saved && saved !== user) Object.assign(user, saved);
    } else {
      saveUser(user, auth.user.userId);
    }
    appendAdminAudit(auth.user.email, 'user.update', user.email, { role: nextRole, name: user.name, credits: user.credits });
    json(res, 200, { ok: true, user: adminUserView(user) });
  }).catch(e => respondError(res, e));
}

