// ★ G0 · 创书因果债务账本：按书隔离存储在 DATA_DIR/causal-debts/<bookId>-debts.json
let creationDebtTracker = null;
/** 懒加载创书因果债务追踪器（存储目录跟随 DATA_DIR，测试可通过 MOLAN_DATA_DIR 隔离）。 */
function getCreationDebtTracker() {
  if (!creationDebtTracker) creationDebtTracker = new CausalDebtTracker({ storeDir: path.join(DATA_DIR, 'causal-debts') });
  return creationDebtTracker;
}

const SOMATIC_REFLEX_PATTERN = /(?:(?:指腹|指肚|拇指|手指)反复?摩挲|食指轻叩(?:桌面|桌案)|指尖(?:骤然)?(?:一顿|悬在半空|僵在半空)|指甲(?:深深)?掐(?:进|入)掌心|骨节捏得泛白|指节泛白|指骨泛白|指骨发白|喉咙发紧|咽喉发紧|喉头发干|喉头一哽|呼吸骤然一窒|呼吸乱了一拍|按揉发胀的太阳穴|后槽牙咬得咯咯作响|咬紧后槽牙|喉结上下滚动|震得脚底发木|虎口发麻|耳膜生疼|脑仁剧痛|气血翻涌|喉头一甜)/gu;

/**
 * 场景能级与躯体应激配比门禁：读取合同能级（emotionIntensity/intensity/tension，0-10），
 * 低能级（≤4）场景出现 ≥1 处应激套话即 warning；中高能级累计 ≥3 处才 warning；≥6 处升级 blocker。
 * 返回 { issue, metrics }，issue 为 null 表示通过。
 */
function evaluateSomaticGate(content, contract) {
  const text = String(content || '');
  const hits = [];
  for (const m of text.matchAll(SOMATIC_REFLEX_PATTERN)) { hits.push(m[0]); if (hits.length >= 40) break; }
  const c = contract && typeof contract === 'object' ? contract : {};
  const rawLevel = [c.emotionIntensity, c.intensity, c.tension, c.energyLevel, c.rhythm && c.rhythm.intensity]
    .map(v => Number(v)).find(v => Number.isFinite(v));
  const level = Number.isFinite(rawLevel) ? Math.max(0, Math.min(10, rawLevel)) : 5;
  const perKilo = text.length ? Math.round(hits.length / Math.max(1, text.length / 1000) * 100) / 100 : 0;
  const metrics = { level, hits: hits.length, perKilo, samples: [...new Set(hits)].slice(0, 5) };
  let issue = null;
  if (hits.length >= 6) {
    issue = { severity: 'blocker', category: 'somatic', description: '躯体应激套话 ' + hits.length + ' 处（如「' + metrics.samples.join('」「') + '」），已形成模型条件反射式写法', suggestion: '改写为外部物理反馈或直接动作；低能级场景平稳拿放、平稳说话' };
  } else if (level <= 4 && hits.length >= 1) {
    issue = { severity: 'warning', category: 'somatic', description: '本章能级 ' + level + '（日常/低张力）却出现 ' + hits.length + ' 处躯体应激套话（「' + metrics.samples.join('」「') + '」）', suggestion: '低能级场景不写神经反射，删去或换成自然白描' };
  } else if (hits.length >= 3) {
    issue = { severity: 'warning', category: 'somatic', description: '躯体应激套话累计 ' + hits.length + ' 处（「' + metrics.samples.join('」「') + '」），超出能级 ' + level + ' 的合理配比', suggestion: '保留最多 1-2 处最关键的生理反应，其余改为物理客体或对白' };
  }
  return { issue, metrics };
}

/**
 * 校验模型审计 issue 的 quote 是否能在正文中逐字定位（空白归一后）。
 * 定位失败：blocker 降级 warning，并加 unverified=true；info/warning 只加标记。
 */
function verifyModelAuditQuotes(items, content) {
  const normalize = value => String(value || '').replace(/\s+/g, '');
  const haystack = normalize(content);
  return (Array.isArray(items) ? items : []).filter(item => item && typeof item === 'object').map(item => {
    const quote = normalize(item.quote || item.position || '');
    if (!quote) return item;
    if (quote.length >= 4 && haystack.includes(quote)) return { ...item, verified: true };
    const next = { ...item, unverified: true };
    if (String(item.severity) === 'blocker') {
      next.severity = 'warning';
      next.description = '[引文未能在正文定位，已降级] ' + String(item.description || '');
    }
    return next;
  });
}

/**
 * 审计通过后登记本章因果债务：承诺（newPromises）记 arc 债，代价/副作用类规则记 micro 债，
 * 再补充正文启发式提取的代价种子；按 seed 去重，返回本次新增与当前活跃概况。
 */
function recordChapterCausalDebts(bookId, chapterNo, content, ledgerDelta) {
  const tracker = getCreationDebtTracker();
  const store = tracker.loadBookDebts(bookId);
  const existing = new Set((store.debts || []).map(d => String(d.seed || '').trim()).filter(Boolean));
  const candidates = [];
  const delta = ledgerDelta && typeof ledgerDelta === 'object' ? ledgerDelta : {};
  (Array.isArray(delta.newPromises) ? delta.newPromises : []).forEach(p => {
    const seed = String(p && (p.text || p) || '').trim().slice(0, 80);
    if (seed) candidates.push({ type: 'arc', seed, immediateCost: '第' + chapterNo + '章立下的承诺/威胁' });
  });
  (Array.isArray(delta.newRules) ? delta.newRules : []).forEach(r => {
    const kind = String(r && r.kind || '');
    const seed = String(r && r.text || '').trim().slice(0, 80);
    if (seed && /代价|副作用/.test(kind)) candidates.push({ type: 'micro', seed, immediateCost: '第' + chapterNo + '章付出的' + kind });
  });
  tracker.extractPotentialDebts(content, chapterNo).forEach(c => candidates.push(c));
  const added = [];
  for (const c of candidates) {
    if (added.length >= 4) break;
    if (!c.seed || existing.has(c.seed)) continue;
    existing.add(c.seed);
    added.push(tracker.recordDebt(bookId, { ...c, originChapter: chapterNo }));
  }
  const { active, matured } = tracker.getActiveDebts(bookId, chapterNo + 1);
  return { added: added.map(d => ({ id: d.id, type: d.type, seed: d.seed, maturationChapter: d.maturationChapter })), activeCount: active.length, maturedCount: matured.length };
}

/** GET /api/creation-books/:id/debts?chapterNo= —— 返回下一章起草可注入的因果债务提示块与明细。 */
function handleCreationBookDebts(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const book = loadCreationBookForAuth(id, auth, projectScope.PROJECT_ROLES);
  if (!book) return json(res, 404, { error: '创作书不存在或无权访问' });
  const q = queryParamsFromUrl(req.url);
  const chapterNo = Math.max(1, Number(q.chapterNo) || (Number(book.current_chapter_no) || 0) + 1);
  const recovery = require('./lib/benchmark-commit').recoverPendingCommitDebts(db, book.id, recordChapterCausalDebts);
  const tracker = getCreationDebtTracker();
  const { active, matured } = tracker.getActiveDebts(book.id, chapterNo);
  const block = tracker.buildDebtPromptInjection(book.id, chapterNo);
  json(res, 200, { ok: true, chapterNo, block: block.slice(0, 1800), active, matured, recovery });
}

async function handleCreationBookChapterAuditImpl(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const book = loadCreationBookForAuth(id, auth, projectScope.WRITE_ROLES);
  if (!book) return json(res, 404, { error: '创作书不存在或无权访问' });
  if (!canSpendCreationBook(book, auth)) return json(res, 403, { error: '当前账户没有该创作书的生成额度权限', code: 'spend_forbidden' });
  let body = {}; try { body = await readBody(req).catch(() => ({})); } catch (_) {}
  const content = String(body.content || '');
  const chapterNo = Math.max(1, Number(body.chapterNo) || 1);
  const current = creationBibleForBook(book.id);
  const issues = [];
  if (!content.trim()) issues.push({ severity: 'blocker', category: 'content', description: '正文为空', suggestion: '生成正文后再提交' });
  else if (content.replace(/\s/g, '').length < 300) issues.push({ severity: 'blocker', category: 'content', description: '正文少于 300 字', suggestion: '补充完整场景' });
  const forbiddenIssues = checkForbiddenTerms(content, creationForbiddenTerms(current.payload));
  issues.push(...forbiddenIssues);
  const contract = body.contract && typeof body.contract === 'object' ? body.contract : {};
  const contractValidation = deterministicContractValidation({ chapterNo, ...contract });
  contractValidation.findings.forEach(item => issues.push({ severity: item.severity, category: 'contract', description: item.description, suggestion: '修订章节合同或正文' }));
  // ★ M2 字数硬控制：偏离合同目标 ±30% 记 warning
  const targetWords = Number(current.payload && current.payload.taskConstraints && current.payload.taskConstraints.chapterWordTarget) || 2000;
  const actualWords = content.replace(/\s/g, '').length;
  if (actualWords > 0 && (actualWords < targetWords * 0.7 || actualWords > targetWords * 1.3)) {
    issues.push({ severity: 'warning', category: 'pacing', description: '字数 ' + actualWords + ' 偏离目标 ' + targetWords + ' 超过 ±30%', suggestion: actualWords > targetWords ? '删减过渡句与重复状态描写，压缩至 ' + Math.round(targetWords * 0.9) + '-' + Math.round(targetWords * 1.1) + ' 字' : '补充场景细节至 ' + Math.round(targetWords * 0.9) + '-' + Math.round(targetWords * 1.1) + ' 字' });
  }
  // ★ M2 重复注水检测：段落 20 字前缀去重 + 高频重复句
  {
    const paras = content.split(/\n+/).map(p => p.trim()).filter(p => p.length >= 12);
    const seenPrefix = new Map();
    const dupParas = [];
    paras.forEach((p, idx) => {
      const key = p.slice(0, 20);
      if (seenPrefix.has(key)) dupParas.push({ first: seenPrefix.get(key), second: idx + 1, text: key });
      else seenPrefix.set(key, idx + 1);
    });
    if (dupParas.length) {
      issues.push({ severity: 'blocker', category: 'redundancy', description: '发现 ' + dupParas.length + ' 处疑似重复段落（如「' + (dupParas[0].text || '') + '…」）', suggestion: '删除重复段落，只保留首处并合并差异信息' });
    }
    const sentences = content.split(/(?<=[。！？])/u).map(x => x.trim()).filter(x => x.length >= 15);
    const sentCount = new Map();
    sentences.forEach(x => { const k = x.slice(0, 18); sentCount.set(k, (sentCount.get(k) || 0) + 1); });
    const repeatedSentences = [...sentCount.entries()].filter(([k, n]) => n >= 3);
    if (repeatedSentences.length) {
      issues.push({ severity: 'warning', category: 'redundancy', description: repeatedSentences.length + ' 个句子/状态短语重复出现 3 次以上（如「' + repeatedSentences[0][0] + '…」），疑似状态复述', suggestion: '状态首次详写，后续只写变化量' });
    }
  }
  // ★ G0 场景能级与躯体动作配比门禁（确定性，零模型成本）：
  //   合同能级低（emotionIntensity/intensity ≤4）时出现任何“指腹摩挲/喉头一哽”类应激套话即报；能级高时累计 ≥3 处才报。
  const somaticGate = evaluateSomaticGate(content, contract);
  if (somaticGate.issue) issues.push({ ...somaticGate.issue, severity: 'warning', heuristicOnly: true });
  // ★ G1 全题材叙事与情绪门禁（高潮反响/悬疑沙箱/都市反派/女频宅斗/历史礼制）：
  const genreAudits = runGenreNarrativeAudits(content, contract, String(body.genre || current.payload.genre || ''));
  if (genreAudits.issues && genreAudits.issues.length) {
    issues.push(...genreAudits.issues.map(item => ({ ...item, heuristicOnly: true })));
  }
  const user = getUserByEmail(auth.user.email) || { email: auth.user.email };
  const creationModelId = resolveModelForUser(user, body.modelId || currentDefaultModel());
  // ★ 事实账本随审计走：本章确立的新事实/规则/承诺增量登记，供后续章节检索注入。
  const factLedger = body.factLedger && typeof body.factLedger === 'object' && !Array.isArray(body.factLedger) ? body.factLedger : null;
  const semanticAudit = await benchmarkPipeline.evidenceAudit({
    callModel: (_auth, options) => callMolanChat(String(req.headers.authorization || ''), user, { ...options, requireComplete: true })
  }, auth, {
    text: content, contract, factLedger, modelId: creationModelId, targetWords,
    genre: String(body.genre || current.payload.genre || ''),
    continuity: {
      premise: current.payload.bookPremise,
      worldRules: current.payload.worldRules || [],
      characters: (current.payload.characters || []).filter(item => content.includes(String(item.name || '')) || String(contract.viewpoint || '').includes(String(item.name || ''))),
      relationships: current.payload.relationships || [],
      goldenFinger: current.payload.goldenFinger,
      openForeshadows: (current.payload.foreshadowLedger || []).filter(item => item && !['paid', 'resolved'].includes(item.status)),
      previousSnapshots: loadCreationSnapshots(book.id, 0).slice(0, 2)
    }
  });
  const auditOutput = { json: semanticAudit, usage: semanticAudit.usage };
  const modelAudit = semanticAudit;
  issues.push(...semanticAudit.issues.map(item => ({ ...item, description: item.problem, suggestion: item.fixHint })));
  if (semanticAudit.status === 'incomplete') issues.push({ severity: 'blocker', category: 'review_coverage', description: '语义审计未完成：' + semanticAudit.incompleteReasons.join('、') });
  // 读取已提交快照用于确定性原创指标与保留符合度（不阻断提交，仅记录）
  const snapshots = loadCreationSnapshots(book.id, 0).slice(0, 200);
  // L1 结构级原创比对（纯本地，零模型成本）：事件链 LCS 相似度 + 人物功能集合 Jaccard 相似度
  const structuralSimilarity = computeStructuralSimilarity(current.payload, snapshots);
  if (structuralSimilarity.blocked) {
    issues.push({ severity: 'blocker', category: 'originality', metric: 'structural', eventChainLcsRatio: structuralSimilarity.eventChainLcsRatio, functionSetJaccard: structuralSimilarity.functionSetJaccard, description: '结构级相似度过高（事件链 LCS ' + (structuralSimilarity.eventChainLcsRatio == null ? 'N/A' : structuralSimilarity.eventChainLcsRatio.toFixed(2)) + ' / 功能集合 Jaccard ' + (structuralSimilarity.functionSetJaccard == null ? 'N/A' : structuralSimilarity.functionSetJaccard.toFixed(2)) + '），疑似结构级抄袭', suggestion: '重写本章的事件编排与人物功能分配，避免照搬源书骨架' });
  }
  const originality = creationOriginalityGate(current.payload, modelAudit, forbiddenIssues, snapshots);
  originality.issues.forEach(item => issues.push(item));
  // R3 · 骨架保留符合度：violated 项记为 warning（不阻断），并累计写入 qualityState.retentionIssues
  const retentionCompliance = computeRetentionCompliance(current.payload, snapshots, current.payload.sourceStructure || {});
  retentionCompliance.items.forEach(item => {
    if (item.status === 'violated') issues.push({ severity: 'warning', category: 'retention', key: item.key, description: item.detail, suggestion: '请对照拆书骨架，尽量保全保留级对应的结构特征' });
  });
  if (retentionCompliance.violatedCount > 0) {
    try {
      const qs = current.payload.qualityState && typeof current.payload.qualityState === 'object' ? current.payload.qualityState : {};
      const retentionIssues = Array.isArray(qs.retentionIssues) ? qs.retentionIssues : [];
      retentionIssues.push({ auditAt: Date.now(), chapterNo, items: retentionCompliance.items.map(i => ({ key: i.key, level: i.level, status: i.status, detail: i.detail }) ) });
      current.payload.qualityState = { ...qs, retentionIssues: retentionIssues.slice(-50) };
      const nextBibleVersion = current.version + 1;
      const now = Date.now();
      db.exec('BEGIN');
      try {
        // ★ P2-8 · CAS 写入：版本推进必须基于读取时的版本号，用户并发修订时跳过本次
        // retention 记录（下一轮审计会再累计），而不是覆盖用户的修订。
        const cas = db.prepare('UPDATE creation_bibles SET current_version = ?, updated_at = ? WHERE id = ? AND current_version = ?')
          .run(nextBibleVersion, now, current.bibleId, current.version);
        if (Number(cas.changes || 0) !== 1) {
          db.exec('ROLLBACK');
          console.warn('[creation] 审计写 retention 版本时检测到圣经并发更新，跳过 book=' + book.id + ' version=' + current.version);
        } else {
          db.prepare('INSERT INTO creation_bible_versions (id,bible_id,version,payload_json,payload_hash,source_brief_id,parent_version,change_summary,created_by,created_at) VALUES (?,?,?,?,?,?,?,?,?,?)')
            .run('bv_' + current.bibleId + '_' + nextBibleVersion, current.bibleId, nextBibleVersion, JSON.stringify(current.payload), sha256Text(JSON.stringify(current.payload)), book.source_brief_id, current.version, '审计累计保留符合度问题（版本 +1）', auth.user.email, now);
          db.exec('COMMIT');
          current.version = nextBibleVersion;
        }
      } catch (error) { try { db.exec('ROLLBACK'); } catch (_) {} throw error; }
    } catch (error) { console.error('[creation] 审计累计 retention 问题失败 book=' + book.id + ':', error && error.message || error); }
  }
  const blockers = issues.filter(item => String(item && item.severity) === 'blocker');
  // ★ P0-1b · 审计结果落库：commit 端点据此做服务端复核，前端上报的 auditStatus 不再被信任
  const auditPassed = blockers.length === 0 && semanticAudit.passed === true && !!content.trim();
  const causalDebts = { status: 'pending_commit' };
  const qualityGate = !auditPassed || originality.status === 'blocked' ? 'blocked' : originality.status === 'passed' ? 'passed' : 'passed_with_structural_pending';
  const auditUsage = auditOutput.usage || null;
  let auditCreditCost = 0;
  if (auditUsage && Number.isFinite(Number(auditUsage.creditCost))) auditCreditCost = Number(auditUsage.creditCost);
  else if (auditUsage && Number.isFinite(Number(auditUsage.totalTokens))) {
    try { auditCreditCost = creditCostForUser(user, creationModelId, Number(auditUsage.totalTokens)); } catch (_) {}
  }
  const factLedgerDelta = modelAudit && modelAudit.factLedgerDelta && typeof modelAudit.factLedgerDelta === 'object' ? modelAudit.factLedgerDelta : { newRules: [], newPromises: [], byEntity: {}, updates: [] };
  const bibleVersion = Number(current.version) || 0;
  const stateVersion = Number(book.current_state_version) || 0;
  const planHash = sha256Text(JSON.stringify(current.payload && current.payload.creationPlan || {}));
  const contextHash = sha256Text(JSON.stringify({ bookId: book.id, chapterNo, bibleVersion, stateVersion, planHash, genre: body.genre || current.payload.genre || '', targetWords, contract, factLedger, continuity: { premise: current.payload.bookPremise, worldRules: current.payload.worldRules || [], relationships: current.payload.relationships || [], openForeshadows: current.payload.foreshadowLedger || [] } }));
  const deltaHash = sha256Text(JSON.stringify(factLedgerDelta));
  const auditPayload = { passed: auditPassed, qualityGate, originality, structuralSimilarity, retentionCompliance, summary: modelAudit && modelAudit.summary || (blockers.length ? '存在阻断问题' : originality.status === 'pending' ? '确定性审计通过，结构级原创审计待事件抽取' : '确定性审计通过'), issues: issues.slice(0, 60), blockerCount: blockers.length, unverifiedIssueCount: issues.filter(item => item && item.unverified).length, contentLength: content.length, targetWords, somaticGate: somaticGate.metrics, causalDebts, source: 'creation-bible', bibleVersion, stateVersion, planHash, contextHash, deltaHash, factLedgerDelta };
  Object.assign(auditPayload, { protocol: 'benchmark-local-v2', contentHash: sha256Text(content), semanticAudit, status: auditPassed ? 'passed' : 'needs_review', humanReviewStatus: 'pending' });
  try {
    if (dbReady()) {
      db.prepare(`INSERT INTO creation_chapter_audits
        (id,book_id,user_email,chapter_no,content_hash,passed,quality_gate,originality_status,blocker_count,
         audit_credit_cost,result_json,created_at,bible_version,state_version,context_hash,delta_hash,plan_hash,
         actor_user_id,workspace_id,project_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
        .run(
          'cca_' + book.id + '_' + chapterNo + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
          book.id, auth.user.email, chapterNo, sha256Text(content), auditPassed ? 1 : 0, qualityGate,
          String(originality.status || ''), blockers.length, auditCreditCost, JSON.stringify(auditPayload), Date.now(),
          bibleVersion, stateVersion, contextHash, deltaHash, planHash,
          String(auth.user.userId || projectScope.stableUserId(auth.user.email)),
          book.workspace_id || '', book.project_id || book.novel_id || '');
    }
  } catch (error) { console.error('[creation] 章节审计结果落库失败 book=' + book.id + ' chapter=' + chapterNo + ':', error && error.message || error); }
  json(res, 200, { ok: true, audit: auditPayload, usage: auditOutput.usage || null });
}

// ★ R4 · 结构原创门禁（L1 确定性优先）：优先用确定性算法计算事件链/角色组合/地图拓扑相似度，
// 确定性数据不足的字段才回退模型估值；两者皆缺才 pending。机制/关系类指标仅由模型估值。
// @param {object} payload - 新书圣经负载
// @param {object} modelAudit - 模型审计返回（含 structureMetrics 估值）
// @param {Array} forbiddenIssues - 禁止复制项命中（blocker）
// @param {Array} snapshots - 已提交章节快照（含 recentFacts 事件链）
// @param {object} sourcePayload - 可选的原书圣经负载（提供 sourceStructure 角色/地图/事件）
// @returns {{status:string, forbiddenCopyHitRate:number, thresholds:object, metrics:object, missing:Array, issues:Array, deterministic:object}}
function creationOriginalityGate(payload, modelAudit, forbiddenIssues, snapshots, sourcePayload) {
  const metrics = modelAudit && modelAudit.structureMetrics && typeof modelAudit.structureMetrics === 'object' ? modelAudit.structureMetrics : {};
  const thresholds = { eventChainSimilarity: 0.35, roleCombinationSimilarity: 0.4, mapTopologySimilarity: 0.45, relationshipGraphSimilarity: 0.45, goldenFingerMechanismSimilarity: 0.35 };
  const names = Object.keys(thresholds);
  // 原书结构来源：优先取传入 sourcePayload 的 sourceStructure，其次取新书自身的 sourceStructure（由拆书简报 seed）
  const src = (sourcePayload && sourcePayload.sourceStructure) || (payload && payload.sourceStructure) || {};
  // 确定性计算：term/拓扑/角色组合 优先；机制与关系图无确定性来源，沿用模型估值
  const deterministic = {};
  const orderedSnapshots = (Array.isArray(snapshots) ? snapshots : []).filter(snapshot => snapshot && Array.isArray(snapshot.recentFacts)).sort((a, b) => Number(a.chapterNo) - Number(b.chapterNo));
  const newEvents = orderedSnapshots.flatMap(snapshot => snapshot.recentFacts).length ? orderedSnapshots.flatMap(snapshot => snapshot.recentFacts) : (payload && Array.isArray(payload.timeline) ? payload.timeline : []);
  const srcEvents = Array.isArray(src.events) && src.events.length ? src.events : Array.isArray(src.timeline) ? src.timeline : Array.isArray(src.framework && src.framework.events) ? src.framework.events : [];
  const ec = computeEventChainLCS(newEvents, srcEvents);
  if (Number.isFinite(ec)) deterministic.eventChainSimilarity = ec;
  const sourceCharacters = Array.isArray(src.characters) && src.characters.length ? src.characters : src.roles;
  const rc = computeRoleCombinationJaccard(payload && payload.characters, sourceCharacters);
  if (Number.isFinite(rc)) deterministic.roleCombinationSimilarity = rc;
  const sourceMap = src.map && Array.isArray(src.map.nodes) && src.map.nodes.length ? src.map : src.worldMap;
  const mp = computeMapTopologySimilarity(payload && payload.map, sourceMap);
  if (Number.isFinite(mp)) deterministic.mapTopologySimilarity = mp;
  const normalized = {};
  const missing = [];
  const used = {};
  names.forEach(name => {
    // 确定性优先
    if (typeof deterministic[name] === 'number' && Number.isFinite(deterministic[name])) {
      normalized[name] = deterministic[name]; used[name] = 'deterministic';
      return;
    }
    // 回退模型估值
    const rawValue = metrics[name];
    const value = rawValue === null || rawValue === undefined || rawValue === '' ? NaN : Number(rawValue);
    if (Number.isFinite(value) && value >= 0 && value <= 1) { normalized[name] = value; used[name] = 'model'; return; }
    missing.push(name); used[name] = 'missing';
  });
  const issues = [];
  if (forbiddenIssues.length) issues.push({ severity: 'blocker', category: 'originality', description: '禁止复制项命中率必须为 0', suggestion: '替换命中的原书专属名词、事件或序列' });
  names.forEach(name => {
    const value = normalized[name];
    if (Number.isFinite(value) && value >= thresholds[name]) issues.push({ severity: 'blocker', category: 'originality', metric: name, description: name + ' 达到 ' + value.toFixed(2) + '，超过门禁 ' + thresholds[name].toFixed(2), suggestion: '重写对应的具体事件、功能组合、拓扑关系或能力机制' });
  });
  if (missing.length) {
    issues.push({ severity: 'warning', category: 'originality', description: '结构级原创审计待正文事件、地图和关系数据齐备后执行：' + missing.join('、'), suggestion: '先完成本章正文和状态抽取，再运行结构原创审计' });
    return { status: issues.some(item => item.severity === 'blocker') ? 'blocked' : 'pending', forbiddenCopyHitRate: forbiddenIssues.length ? 1 : 0, thresholds, metrics: normalized, missing, issues, deterministic: { values: deterministic, used } };
  }
  return { status: issues.some(item => item.severity === 'blocker') ? 'blocked' : 'passed', forbiddenCopyHitRate: forbiddenIssues.length ? 1 : 0, thresholds, metrics: normalized, missing: [], issues, deterministic: { values: deterministic, used } };
}

// ★ Q3 · 确定性合同验证（方案 8.5.3）：字段/枚举/引用合法性由规则先查，语义留给模型。
function deterministicContractValidation(contract) {
  const c = contract && typeof contract === 'object' ? contract : {};
  const findings = [];
  const add = (field, ok, note) => { if (!ok) findings.push({ severity: 'blocker', category: 'contract', field, description: note }); };
  add('chapterNo', Number(c.chapterNo) > 0, 'chapterNo 必须为正整数');
  add('goal', String(c.goal || '').trim().length > 0, 'goal 不能为空');
  add('protagonistAction', String(c.protagonistAction || '').trim().length > 0, 'protagonistAction 不能为空（主角必须有主动动作）');
  add('opposition', String(c.opposition || '').trim().length > 0, 'opposition 不能为空（必须有阻力来源）');
  add('informationChange', String(c.informationChange || '').trim().length > 0, 'informationChange 不能为空（必须有信息变化）');
  add('irreversibleResult', String(c.irreversibleResult || '').trim().length > 0, 'irreversibleResult 不能为空（必须有不可逆结果）');
  const VALID_ACTIONS = ['plant', 'advance', 'reinforce', 'mislead', 'payoff', 'recover'];
  (Array.isArray(c.foreshadowActions) ? c.foreshadowActions : []).forEach((f, i) => {
    if (f && !VALID_ACTIONS.includes(String(f.action))) findings.push({ severity: 'warning', category: 'contract', field: 'foreshadowActions[' + i + ']', description: 'action 必须 ∈ [' + VALID_ACTIONS.join('|') + ']' });
  });
  return {
    status: findings.some(f => f.severity === 'blocker') ? 'failed' : (findings.length ? 'needs_review' : 'passed'),
    findings,
    blockerCount: findings.filter(f => f.severity === 'blocker').length
  };
}
// ★ Q3 · 原创检查：正文命中禁止复制项即阻断（方案 9.5 确定性第一层）
// P2-12 · 匹配前对正文与词项做归一化（全角→半角、去空白、小写），
// 防止「萧 炎」「萧炎」加空格或全角字符绕过词面检测。
function normalizeForbiddenMatchText(value) {
  return String(value || '').toLowerCase()
    .replace(/[\uFF01-\uFF5E]/g, ch => String.fromCharCode(ch.charCodeAt(0) - 0xFEE0))
    .replace(/\s+/g, '');
}
function checkForbiddenTerms(text, forbiddenList) {
  const list = Array.isArray(forbiddenList) ? forbiddenList.map(String).filter(Boolean) : [];
  const body = String(text || '');
  if (!body || !list.length) return [];
  const normalizedBody = normalizeForbiddenMatchText(body);
  return list.filter(t => {
    if (t.length < 2) return false;
    return normalizedBody.includes(normalizeForbiddenMatchText(t));
  }).map(t => ({ severity: 'blocker', category: 'originality', term: t.slice(0, 60), description: '正文出现禁止复制项「' + t.slice(0, 60) + '」' }));
}

/** 检测人物姓名是否共享汉字，返回需要重命名的冲突对。 */
function characterNameOverlapIssues(payload) {
  const names = (Array.isArray(payload && payload.characters) ? payload.characters : [])
    .map(item => typeof item === 'string' ? item : item && (item.name || item.title) || '')
    .map(value => String(value).trim())
    .filter(Boolean);
  const issues = [];
  for (let leftIndex = 0; leftIndex < names.length; leftIndex += 1) {
    const left = names[leftIndex];
    const leftChars = new Set([...left].filter(char => /[\u4e00-\u9fff]/u.test(char)));
    if (!leftChars.size) continue;
    for (let rightIndex = leftIndex + 1; rightIndex < names.length; rightIndex += 1) {
      const right = names[rightIndex];
      const shared = [...new Set([...right].filter(char => leftChars.has(char)))];
      if (shared.length) issues.push({ left, right, shared });
    }
  }
  return issues;
}

// ★ R2 · Bible seed 原创门禁（确定性）：阻止原书专属名词进入创作圣经，并校验结构性完整。
// 对人物/地图节点/世界观/关系的名称与 forbiddenTerms 做词面命中（≥2 字完全匹配）；结构缺失（人物 <3、地图节点 <3、金手指类型为空）同样拒绝。
/** 校验创作圣经是否命中原书专名、缺少必要资产或存在人物姓名重叠。 */
function creationBibleSeedValidation(payload, forbiddenTerms) {
  const clean = list => (Array.isArray(list) ? list : []).map(item => {
    if (typeof item === 'string') return item;
    if (!item || typeof item !== 'object') return '';
    return item.term || item.name || item.title || item.value || '';
  }).map(item => String(item).trim()).filter(item => item.length >= 2);
  const terms = [...new Set(clean(forbiddenTerms))];
  // 只收集实体名称和关系两端名称；简介、分类和描述属于新作语义，不应误触发首版门禁。
  const checks = [];
  const addNames = (field, list, keys) => {
    (Array.isArray(list) ? list : []).forEach(item => {
      const values = typeof item === 'string' ? [item] : item && typeof item === 'object'
        ? keys.map(key => item[key]).filter(value => value !== undefined && value !== null)
        : [];
      values.map(value => String(value).trim()).filter(Boolean).forEach(value => checks.push({ field, value }));
    });
  };
  addNames('characters', payload && payload.characters, ['name', 'title']);
  addNames('worldbuilding', payload && payload.worldbuilding, ['name', 'title']);
  addNames('map.nodes', payload && payload.map && payload.map.nodes, ['name', 'title']);
  addNames('relationships', payload && payload.relationships, ['name', 'title', 'from', 'to', 'source', 'target']);
  const hits = [];
  const seen = new Set();
  checks.forEach(({ field, value }) => terms.forEach(term => {
    if (!value.includes(term)) return;
    const key = field + '\u0000' + value + '\u0000' + term;
    if (!seen.has(key)) { seen.add(key); hits.push({ field, value: value.slice(0, 120), term: term.slice(0, 60) }); }
  }));
  // 结构性缺失检查
  const missing = [];
  const charCount = (Array.isArray(payload && payload.characters) ? payload.characters : []).filter(c => c && String(c.name || c.title || '').trim()).length;
  if (charCount < 3) missing.push({ field: 'characters', reason: '人物 (' + charCount + ') 少于 3 个' });
  const nodeCount = (payload && payload.map && Array.isArray(payload.map.nodes) ? payload.map.nodes : []).filter(node => node && String(node.name || node.title || '').trim()).length;
  if (nodeCount < 3) missing.push({ field: 'map.nodes', reason: '地图节点 (' + nodeCount + ') 少于 3 个' });
  const gfType = String(payload && payload.goldenFinger && payload.goldenFinger.type || '').trim();
  if (!gfType) missing.push({ field: 'goldenFinger.type', reason: '金手指类型为空' });
  const nameOverlaps = characterNameOverlapIssues(payload);
  nameOverlaps.forEach(item => missing.push({ field: 'characters', reason: '人物姓名「' + item.left + '」与「' + item.right + '」共享汉字「' + item.shared.join('、') + '」，请重命名其中之一', code: 'name_overlap', names: [item.left, item.right], shared: item.shared }));
  return { ok: hits.length === 0 && missing.length === 0, hits, missing, nameOverlaps };
}

// ★ R4 · 事件链 LCS 相似度（确定性）：把"动作类型+角色功能+结果"归一化后，比较新书事件序列与原书事件序列的最长公共子序列占比。
// @param {Array} newEvents - 新书事件快照（recentFacts）
// @param {Array} sourceEvents - 原书事件序列
// @returns {number|null} 0~1 相似度；任一序列为空或不足时返回 null（表示确定性数据不足）
function computeEventChainLCS(newEvents, sourceEvents) {
  const norm = ev => {
    if (typeof ev === 'string') return String(ev).replace(/[\s，。,.！!？?、]/g, '').slice(0, 40);
    if (!ev || typeof ev !== 'object') return '';
    const act = String(ev.action || ev.type || ev.eventType || '').slice(0, 20);
    const role = String(ev.role || ev.character || ev.subject || '').slice(0, 20);
    const result = String(ev.result || ev.outcome || ev.consequence || '').slice(0, 20);
    return (act + '|' + role + '|' + result).replace(/[\s]/g, '');
  };
  // ★ P2 · 规模护栏：快照×事件膨胀时截断为最新 400 条（新书）/前 400 条（原书），
  // DP 上限 16 万格，防止审计请求在事件链上出现平方级耗时。
  const LCS_MAX_EVENTS = 400;
  const a = (Array.isArray(newEvents) ? newEvents : []).map(norm).filter(Boolean).slice(-LCS_MAX_EVENTS);
  const b = (Array.isArray(sourceEvents) ? sourceEvents : []).map(norm).filter(Boolean).slice(0, LCS_MAX_EVENTS);
  if (a.length < 2 || b.length < 2) return null;
  // LCS DP（序列长度通常很小，O(n*m) 足够）
  const n = a.length, m = b.length;
  const dp = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0));
  for (let i = 1; i <= n; i++) for (let j = 1; j <= m; j++) {
    dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  }
  const lcs = dp[n][m];
  return Math.min(1, lcs / Math.max(n, m));
}

// ★ R4 · 人物功能组合 Jaccard 相似度（确定性）：比较新书人物功能标签集合与原书角色功能集合。
// @param {Array} newCharacters - 新书人物
// @param {Array} sourceCharacters - 原书角色功能集合
// @returns {number|null} 0~1；集合为空或不足时返回 null
function computeRoleCombinationJaccard(newCharacters, sourceCharacters) {
  const collect = list => new Set((Array.isArray(list) ? list : []).flatMap(item => {
    if (typeof item === 'string') return [item.trim()].filter(Boolean);
    if (!item || typeof item !== 'object') return [];
    const tags = [item.role, item.function, item.functionType, item.type]
      .map(v => (v === undefined || v === null) ? '' : String(v));
    if (Array.isArray(item.tags)) tags.push(...item.tags.map(String));
    if (Array.isArray(item.functions)) tags.push(...item.functions.map(String));
    return tags.flatMap(tag => String(tag).split(/[，,、/|]/));
  }).map(t => String(t).trim()).filter(t => t.length >= 2));
  const A = collect(newCharacters), B = collect(sourceCharacters);
  if (!A.size || !B.size) return null;
  let inter = 0;
  A.forEach(x => { if (B.has(x)) inter++; });
  return inter / (A.size + B.size - inter);
}

// ★ R4 · 地图拓扑相似度（确定性）：比较新书地图层级树与原书地图层级树。
// 节点按 "父级|名称" 归一化后取集合 Jaccard（容忍子图差异的同时，能捕捉层级同构）。
// @param {object} newMap - 新书地图 {nodes, edges}
// @param {object} sourceMap - 原书地图 {nodes, edges}
// @returns {number|null} 0~1；数据不足时返回 null
function computeMapTopologySimilarity(newMap, sourceMap) {
  const treeify = map => {
    const nodes = Array.isArray(map && map.nodes) ? map.nodes : [];
    const edges = Array.isArray(map && map.edges) ? map.edges : [];
    if (nodes.length < 2) return null;
    const id2name = {};
    nodes.forEach(n => { if (n && (n.id || n.name)) id2name[String(n.id || '') || String(n.name || '')] = String(n.name || n.id || '').trim(); });
    const set = new Set();
    nodes.forEach(n => {
      const name = String(n.name || n.id || '').trim();
      if (name) set.add('|' + name);
    });
    edges.forEach(e => {
      if (!e) return;
      // edges 两种形态：[{source,target}] 或 [{from,to}]，name 可能引用 node.id 或直接是名称
      const fromId = String(e.source || e.from || '').trim();
      const toId = String(e.target || e.to || '').trim();
      const parent = id2name[fromId] || fromId;
      const child = id2name[toId] || toId;
      if (parent && child && parent !== child) set.add(parent + '|' + child);
    });
    const degree = {};
    edges.forEach(edge => {
      if (!edge) return;
      const fromId = String(edge.source || edge.from || '').trim();
      const toId = String(edge.target || edge.to || '').trim();
      if (fromId) degree[fromId] = (degree[fromId] || 0) + 1;
      if (toId) degree[toId] = (degree[toId] || 0) + 1;
    });
    return {
      features: set,
      names: new Set(nodes.map(node => String(node && (node.name || node.title || node.id) || '').trim()).filter(Boolean)),
      nodeCount: nodes.length,
      edgeCount: edges.length,
      degrees: Object.values(degree).sort((a, b) => a - b)
    };
  };
  const A = treeify(newMap), B = treeify(sourceMap);
  if (!A || !B || !A.features.size || !B.features.size) return null;
  const jaccard = (left, right) => {
    let inter = 0;
    left.forEach(value => { if (right.has(value)) inter++; });
    return inter / Math.max(1, left.size + right.size - inter);
  };
  const ratio = (left, right) => Math.min(left, right) / Math.max(1, Math.max(left, right));
  const degreeScore = (left, right) => {
    if (!left.length && !right.length) return 1;
    const length = Math.max(left.length, right.length);
    let same = 0;
    for (let index = 0; index < length; index++) if (left[index] === right[index]) same++;
    return same / Math.max(1, length);
  };
  const structural = (ratio(A.nodeCount, B.nodeCount) + ratio(A.edgeCount, B.edgeCount) + degreeScore(A.degrees, B.degrees)) / 3;
  // 名称只作为直接沿用原书地图的证据；全量改名但保留结构时不会达到 0.45 门禁。
  return structural * 0.4 + jaccard(A.names, B.names) * 0.6;
}

// ★ R3 · 骨架保留符合度（确定性）：按用户保留级别（keep/tune）测量新书对拆书骨架的保留程度。
// 四项测量：金手指进入时机、架构阶段数、开篇节奏节点、章末钩子密度。数据不足返回 insufficient（不阻断）。
// @param {object} payload - 新书圣经负载（含 goldenFinger/architecture、sourceStructure 来自拆书简报）
// @param {Array} snapshots - 已提交章节快照（含 recentFacts、timeline 或章末钩子字段）
// @param {object} sourceStructure - 原书拆书结构，用于对照架构阶段和金手指进入时机
// @returns {{items:Array<{key:string,level:string,status:string,detail:string,skipped?:boolean}>,violatedCount:number}}
function computeRetentionCompliance(payload, snapshots, sourceStructure) {
  const p = payload && typeof payload === 'object' ? payload : {};
  const plan = p.creationPlan && typeof p.creationPlan === 'object' ? p.creationPlan : {};
  const retention = plan.retention && typeof plan.retention === 'object' ? plan.retention : {};
  const src = sourceStructure && typeof sourceStructure === 'object' ? sourceStructure : (p.sourceStructure && typeof p.sourceStructure === 'object' ? p.sourceStructure : {});
  const srcArc = src.architecture && typeof src.architecture === 'object' ? src.architecture : {};
  const srcGF = src.goldenFinger && typeof src.goldenFinger === 'object' ? src.goldenFinger : {};
  const sf = p.goldenFinger && typeof p.goldenFinger === 'object' ? p.goldenFinger : {};
  const chapterValue = value => Number.isFinite(Number(value)) && Number(value) > 0 ? Number(value) : NaN;
  const gfNode = chapterValue(sf.entry) || chapterValue(sf.entryChapter) || NaN;
  const srcGFNode = chapterValue(srcGF.entry) || chapterValue(srcGF.entryChapter) || NaN;
  const items = [];
  const levelOf = key => ['keep', 'tune', 'rewrite'].includes(String(retention[key])) ? String(retention[key]) : 'keep';
  const set = (key, status, detail, skipped = false) => items.push({ key, level: levelOf(key), status: status || 'insufficient', detail, ...(skipped ? { skipped: true } : {}) });
  const snapshotsByChapter = [...new Map((Array.isArray(snapshots) ? snapshots : []).filter(item => item && Number(item.chapterNo) > 0).map(item => [Number(item.chapterNo), item])).values()];
  const factsOf = snapshot => Array.isArray(snapshot && snapshot.recentFacts) ? snapshot.recentFacts : Array.isArray(snapshot && snapshot.timeline) ? snapshot.timeline : [];
  const hasCrisis = facts => facts.some(fact => /危机|冲突|对抗|战斗|袭击|追杀|困境|crisis|conflict|danger|attack/i.test(typeof fact === 'string' ? fact : JSON.stringify(fact || {})));
  const hasHook = snapshot => {
    const direct = ['hook', 'chapterEndHook', 'endingHook', 'nextHook', 'unresolvedQuestion'];
    if (direct.some(key => String(snapshot && snapshot[key] || '').trim())) return true;
    return factsOf(snapshot).some(fact => fact && typeof fact === 'object' && (String(fact.hook || fact.chapterEndHook || fact.nextQuestion || '').trim() || String(fact.result || fact.outcome || fact.conclusion || '').trim()));
  };
  const countStages = value => {
    if (Array.isArray(value)) return value.length;
    if (value && typeof value === 'object') {
      for (const key of ['stages', 'phases', 'volumes', 'arcs']) if (Array.isArray(value[key])) return value[key].length;
      if (Number.isFinite(Number(value.stageCount))) return Number(value.stageCount);
    }
    return 0;
  };

  // 1) 金手指进入时机（keep ≤1 章，tune ≤2 章；rewrite 跳过）
  const gfLevel = levelOf('goldenFinger');
  if (gfLevel === 'rewrite') set('goldenFinger', 'insufficient', '重写级不迁移金手指，跳过测量', true);
  else if (Number.isFinite(gfNode) && Number.isFinite(srcGFNode)) {
    const diff = Math.abs(gfNode - srcGFNode);
    const limit = gfLevel === 'tune' ? 2 : 1;
    set('goldenFinger', diff <= limit ? 'ok' : 'violated', '新书金手指进入第 ' + gfNode + ' 章（原书第 ' + srcGFNode + ' 章），偏差 ' + diff + ' 章，' + gfLevel + ' 级允许 ≤' + limit + ' 章');
  } else if (gfLevel !== 'rewrite') set('goldenFinger', 'insufficient', '金手指进入时机数据不足，待正文抽取后复核');

  // 2) 架构阶段数（keep 相同，tune ±1，rewrite 跳过）
  const archLevel = levelOf('architecture');
  const newStages = countStages(p.architecture) || countStages(p.volumePlan) || countStages(p.arcPlan);
  const srcStages = countStages(srcArc) || countStages(src.framework) || countStages(src.volumePlan);
  if (archLevel === 'rewrite') set('architecture', 'insufficient', '重写级不迁移整体架构，跳过测量', true);
  else if (newStages > 0 && srcStages > 0) {
    const diff = Math.abs(newStages - srcStages);
    const limit = archLevel === 'tune' ? 1 : 0;
    set('architecture', diff <= limit ? 'ok' : 'violated', '新书架构阶段 ' + newStages + '（原书 ' + srcStages + '），' + archLevel + ' 级允许 ±' + limit);
  } else set('architecture', 'insufficient', '新书或原书架构阶段数据不足');

  // 3) 开篇节奏节点：前 3 章快照中应包含首次危机（timeline 有事件）且信息变化累计≥3（keep）或≥2（tune）
  const openLevel = levelOf('opening');
  if (openLevel === 'rewrite') { set('opening', 'insufficient', '重写级不迁移开篇节奏，跳过测量', true); }
  else {
    const first3 = snapshotsByChapter.filter(snapshot => Number(snapshot.chapterNo) <= 3);
    const facts = first3.flatMap(factsOf);
    const evCount = facts.length;
    if (!first3.length) set('opening', 'insufficient', '尚无第 1-3 章快照，开篇节奏待提交后复核');
    else {
      const minChanges = openLevel === 'tune' ? 2 : 3;
      const crisis = hasCrisis(facts);
      set('opening', crisis && evCount >= minChanges ? 'ok' : 'violated', '前 3 章首次危机' + (crisis ? '已出现' : '缺失') + '，信息变化累计 ' + evCount + ' 次，' + openLevel + ' 级要求 ≥' + minChanges);
    }
  }

  // 4) 章末钩子密度：已提交章节中，最后一章快照的 recentFacts/结尾有内容即视为存在钩子（keep ≥70%，tune ≥55%）
  const rhythmLevel = levelOf('rhythm');
  if (rhythmLevel === 'rewrite') { set('rhythm', 'insufficient', '重写级不迁移节奏结构，跳过测量', true); }
  else {
    const snaps = snapshotsByChapter;
    if (!snaps.length) set('rhythm', 'insufficient', '尚无已提交章节，钩子密度待提交后复核');
    else {
      const withHook = snaps.filter(hasHook).length;
      const rate = withHook / snaps.length;
      const minRate = rhythmLevel === 'tune' ? 0.55 : 0.70;
      set('rhythm', rate >= minRate ? 'ok' : 'violated', '已提交 ' + snaps.length + ' 章，章末钩子存在率 ' + (rate * 100).toFixed(0) + '%，' + rhythmLevel + ' 级要求 ≥' + Math.round(minRate * 100) + '%');
    }
  }

  return { items, violatedCount: items.filter(i => i.status === 'violated').length };
}

// ★ 阶段4 · 拆书分页 / 覆盖率 / 校验 / 检索 / 重建 API（大数组按需加载，不一次塞全量结果）
function queryParamsFromUrl(url) {
  const idx = String(url || '').indexOf('?');
  const out = {};
  if (idx < 0) return out;
  new URLSearchParams(String(url).slice(idx + 1)).forEach((v, k) => { out[k] = v; });
  return out;
}

function dissectionPipelineStats(record) {
  const p = (record.meta && record.meta.pipeline) || {};
  let entities = 0, candidates = 0, mentions = 0, events = 0, summaries = 0, claims = 0, units = 0, foreshadows = 0, edges = 0, states = 0;
  if (dbReady()) {
    try { entities = db.prepare('SELECT COUNT(*) n FROM dissection_entities WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { candidates = db.prepare("SELECT COUNT(*) n FROM dissection_entities WHERE dissection_id=? AND status='candidate'").get(record.id).n || 0; } catch (_) {}
    try { mentions = db.prepare('SELECT COUNT(*) n FROM dissection_entity_mentions WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { events = db.prepare('SELECT COUNT(*) n FROM dissection_events WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { summaries = db.prepare('SELECT COUNT(*) n FROM dissection_summaries WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { claims = db.prepare('SELECT COUNT(*) n FROM dissection_claims WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { units = db.prepare('SELECT COUNT(*) n FROM dissection_units WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { foreshadows = db.prepare('SELECT COUNT(*) n FROM dissection_foreshadows WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { edges = db.prepare('SELECT COUNT(*) n FROM dissection_event_edges WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
    try { states = db.prepare('SELECT COUNT(*) n FROM dissection_entity_states WHERE dissection_id=?').get(record.id).n || 0; } catch (_) {}
  }
  return {
    unitTotal: p.unitTotal || units, unitCompleted: p.unitCompleted || 0,
    factCoverage: Number(p.factCoverage || 0), batchTotal: p.batchTotal || 0, batchDone: p.batchDone || 0,
    failedBatches: p.failedBatches || [], aggregated: !!p.aggregated, validationStatus: p.validationStatus || null,
    entities, candidates, mentions, events, summaries, claims, foreshadows, edges, states
  };
}

function handleDissectionCoverage(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const record = loadDissectionRecord(id, auth.user.email);
  if (!record) return json(res, 404, { error: '拆书任务不存在或无权访问' });
  json(res, 200, { ok: true, coverage: dissectionPipelineStats(record) });
}

function handleDissectionUnitsPage(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const record = loadDissectionRecord(id, auth.user.email);
  if (!record) return json(res, 404, { error: '拆书任务不存在或无权访问' });
  const q = queryParamsFromUrl(req.url);
  const limit = Math.min(200, Math.max(1, Number(q.limit) || 50));
  const cursor = Number(q.cursor) || 0;
  if (!dbReady()) return json(res, 200, { ok: true, items: [], next: '' });
  const rows = db.prepare('SELECT id,parent_id,unit_type,ordinal,title,source_start,source_end,char_count,token_estimate FROM dissection_units WHERE dissection_id=? AND ordinal > ? ORDER BY ordinal ASC LIMIT ?').all(id, cursor, limit + 1);
  const hasMore = rows.length > limit;
  const items = rows.slice(0, limit);
  json(res, 200, { ok: true, items, next: hasMore ? items[items.length - 1].ordinal : '' });
}

function handleDissectionEntitiesPage(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const record = loadDissectionRecord(id, auth.user.email);
  if (!record) return json(res, 404, { error: '拆书任务不存在或无权访问' });
  const q = queryParamsFromUrl(req.url);
  const limit = Math.min(200, Math.max(1, Number(q.limit) || 50));
  if (!dbReady()) return json(res, 200, { ok: true, items: [], next: '' });
  let cursor = null;
  const rawCursor = String(q.cursor || '').trim();
  if (rawCursor) {
    try {
      const decoded = JSON.parse(Buffer.from(rawCursor, 'base64url').toString('utf8'));
      if (decoded && Number.isFinite(Number(decoded.mentionCount))) cursor = { mentionCount: Number(decoded.mentionCount), canonicalName: String(decoded.canonicalName || ''), id: String(decoded.id || '') };
    } catch (_) {
      const legacy = Number(rawCursor);
      if (Number.isFinite(legacy)) cursor = { mentionCount: legacy, canonicalName: '', id: '' };
    }
  }
  const sql = cursor
    ? 'SELECT id,canonical_name,entity_type,first_unit_id,last_unit_id,mention_count,status FROM dissection_entities WHERE dissection_id=? AND (mention_count < ? OR (mention_count = ? AND (canonical_name > ? OR (canonical_name = ? AND id > ?)))) ORDER BY mention_count DESC, canonical_name ASC, id ASC LIMIT ?'
    : 'SELECT id,canonical_name,entity_type,first_unit_id,last_unit_id,mention_count,status FROM dissection_entities WHERE dissection_id=? ORDER BY mention_count DESC, canonical_name ASC, id ASC LIMIT ?';
  const rows = cursor
    ? db.prepare(sql).all(id, cursor.mentionCount, cursor.mentionCount, cursor.canonicalName, cursor.canonicalName, cursor.id, limit + 1)
    : db.prepare(sql).all(id, limit + 1);
  const hasMore = rows.length > limit;
  const items = rows.slice(0, limit);
  const last = items[items.length - 1];
  const next = hasMore && last
    ? Buffer.from(JSON.stringify({ mentionCount: Number(last.mention_count) || 0, canonicalName: String(last.canonical_name || ''), id: String(last.id || '') })).toString('base64url')
    : '';
  json(res, 200, { ok: true, items, next });
}

function handleDissectionForeshadowsPage(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const record = loadDissectionRecord(id, auth.user.email);
  if (!record) return json(res, 404, { error: '拆书任务不存在或无权访问' });
  const q = queryParamsFromUrl(req.url);
  const limit = Math.min(300, Math.max(1, Number(q.limit) || 50));
  const cursor = Number(q.cursor) || 0;
  // ★ 阶段2 · 伏笔生命周期：优先读 dissection_foreshadows 台账（含埋设/回收章、相关实体、置信度），回退 result
  let list = [];
  if (dbReady()) {
    try {
      list = db.prepare('SELECT id,title,description,status,strength,setup_chapter,payoff_chapter,related_entity_ids,evidence_ids,confidence FROM dissection_foreshadows WHERE dissection_id = ?').all(id)
        .map(r => ({ id: r.id, title: r.title, description: r.description, status: r.status, strength: r.strength, setupChapter: r.setup_chapter, payoffChapter: r.payoff_chapter, relatedEntityIds: JSON.parse(r.related_entity_ids || '[]'), evidenceIds: JSON.parse(r.evidence_ids || '[]'), confidence: r.confidence }));
    } catch (_) { list = []; }
  }
  if (!list.length) {
    const result = dissectionResultView(record.result);
    list = Array.isArray(result.foreshadowing) ? result.foreshadowing : [];
  }
  if (q.status) list = list.filter(f => String(f.status) === q.status);
  const items = list.slice(cursor, cursor + limit);
  json(res, 200, { ok: true, total: list.length, items, next: cursor + items.length < list.length ? cursor + items.length : '' });
}

function handleDissectionSummariesPage(req, res, id) {
  const auth = getAuthUser(req);
  if (!auth) return json(res, 401, { error: '请先登录' });
  const record = loadDissectionRecord(id, auth.user.email);
  if (!record) return json(res, 404, { error: '拆书任务不存在或无权访问' });
  const q = queryParamsFromUrl(req.url);
  const limit = Math.min(300, Math.max(1, Number(q.limit) || 50));
  const cursor = Number(q.cursor) || 0;
  const type = String(q.type || 'volume');
  // ★ 阶段2 · 四级分层摘要查询：chapter / arc / volume / book
  // 优先读 summaries 表（result_json 只是物化视图，不作为唯一事实来源），缺省回退到 result。
  let list = [];
  if (dbReady()) {
    try {
      const rows = db.prepare('SELECT id, owner_id, content_json, child_ids_json FROM dissection_summaries WHERE dissection_id = ? AND summary_type = ? ORDER BY rowid ASC').all(record.id, type);
      list = rows.map(r => { let c = {}; try { c = JSON.parse(r.content_json || '{}'); } catch (_) {} return { id: r.id, ownerId: r.owner_id, childIds: JSON.parse(r.child_ids_json || '[]'), ...c }; });
    } catch (_) { list = []; }
  }
  if (!list.length) {
    const result = dissectionResultView(record.result);
    if (type === 'chapter') list = result.chapterSummaries || [];
    else if (type === 'arc') list = result.arcSummaries || [];
    else if (type === 'book') list = result.bookSummary ? [result.bookSummary] : [];
    else list = result.volumeSummaries || [];
  }
  const items = list.slice(cursor, cursor + limit);
  json(res, 200, { ok: true, type, total: list.length, items, next: cursor + items.length < list.length ? cursor + items.length : '' });
}

